// Seguridad: token por header + lista blanca de pestañas
const TOKEN = 'REEMPLAZAR_TOKEN_PROXY'; // inventa una clave larga y ponla igual en Lovable
const TABLAS = ['DASH_KPI','BANCOS_MOV','COMPROBANTES_WA','IMPORTACIONES','IMPORTACIONES_PAGOS','CREDITOS','INTERESES','TRANSPORTES_SOLICITUDES','TRANSPORTES_PAGOS','COMPRAS_SYMPHONY','COMPRAS_DETALLE','PROVEEDORES_LOCALES_PAGOS','CONCILIACION','CAT_BANCOS','CAT_TERCEROS'];
const headers = $json.headers || {};
const key = headers['x-api-key'] || headers['X-Api-Key'] || '';
const tabla = ($json.query && $json.query.tabla) || '';
if (key !== TOKEN) return [{ json: { ok: false, status: 401, error: 'Token inválido' } }];
if (!TABLAS.includes(tabla)) return [{ json: { ok: false, status: 400, error: 'Tabla no permitida. Válidas: ' + TABLAS.join(', ') } }];
return [{ json: { ok: true, tabla } }];

const datos = $input.all().map(i => i.json).filter(x => x && Object.keys(x).length);
return [{ json: {
  tabla: $('Validar token y tabla').first().json.tabla,
  actualizado: new Date().toISOString(),
  n: datos.length,
  datos
}}];
